__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"SEERAH",{enumerable:!0,get:function(){return h}});const h=[{id:'birth',when:'570 CE',place:'Makkah',title:'Born in the Year of the Elephant',body:['The Prophet \ufdfa was born in Makkah into the tribe of Quraysh. It was the year Abraha marched on the Kaaba with elephants, and Allah stopped his army with flocks of birds.','His father Abdullah had passed away before he was born. His mother Aminah named him Muhammad.'],source:'Quran 105 (Surah Al-Fil)'},{id:'childhood',when:'570 to 578 CE',age:'0 to 8',place:'Makkah',title:'A childhood of loss and care',body:['As a baby he was nursed in the desert by Halimah as-Sa\u2019diyah, and her family was blessed while he lived with them.','His mother Aminah died when he was six. His grandfather Abdul-Muttalib cared for him, and after his grandfather died, his uncle Abu Talib raised him.']},{id:'amin',when:'About 583 to 605 CE',age:'Youth',place:'Makkah',title:'Al-Amin, the trustworthy',body:['He worked as a shepherd and later as a merchant. People called him al-Amin, the trustworthy, and left their valuables with him.','When the tribes argued over who would put the Black Stone back in the Kaaba, he placed it on a cloak and had every leader lift a corner together, ending the fight.']},{id:'khadijah',when:'595 CE',age:'25',place:'Makkah',title:'Marriage to Khadijah',body:['Khadijah, a respected businesswoman, saw his honesty in trade and proposed marriage. They were married for 25 years, and she was the first person to believe in his message.']},{id:'revelation',when:'610 CE',age:'40',place:'Makkah',title:'The first revelation',body:['He would spend time alone in the cave of Hira on Mount an-Nur. There the angel Jibril came to him and said: "Read!"','The first verses revealed were the start of Surah Al-\u2018Alaq: "Read in the name of your Lord who created."'],source:'Quran 96:1-5, Sahih al-Bukhari 3'},{id:'call',when:'613 CE',age:'43',place:'Makkah',title:'Calling people openly',body:['After three years of inviting people quietly, he called the people of Makkah from the hill of Safa. Many leaders turned against him, and the early Muslims, like Bilal and the family of Yasir, were hurt for their faith.']},{id:'abyssinia',when:'615 CE',place:'Journey',title:'Migration to Abyssinia',body:['To protect them, the Prophet \ufdfa sent a group of Muslims to Abyssinia, where the just Christian king, the Najashi, gave them safety.']},{id:'sorrow',when:'619 CE',age:'49',place:'Ta\u2019if',title:'The Year of Sorrow',body:['His beloved wife Khadijah and his uncle Abu Talib both passed away in the same year.','He went to Ta\u2019if to invite its people, and they drove him out with stones. Even then, he made dua for them instead of against them.']},{id:'isra',when:'About 620 CE',place:'Journey',title:'The Night Journey and Ascension',body:['In one night, Allah took him from Makkah to Masjid al-Aqsa in Jerusalem, and then up through the heavens. On this journey the five daily prayers were made obligatory.'],source:'Quran 17:1'},{id:'hijrah',when:'622 CE \xb7 1 AH',age:'53',place:'Madinah',title:'The Hijrah to Madinah',body:['With Abu Bakr, he left Makkah secretly and hid for three days in the cave of Thawr. The Islamic calendar starts from this year.','In Madinah he built the Prophet\u2019s Mosque and made the Muhajirun (migrants) and Ansar (helpers) brothers to each other.'],source:'Quran 9:40'},{id:'badr',when:'624 CE \xb7 2 AH',place:'Madinah',title:'The Battle of Badr',body:['About 313 Muslims faced an army of around 1,000 from Makkah, and Allah gave them victory. In the same year the qiblah changed to the Kaaba and fasting in Ramadan was made obligatory.'],source:'Quran 3:123, 2:144, 2:183'},{id:'uhud',when:'625 CE \xb7 3 AH',place:'Madinah',title:'The Battle of Uhud',body:['Some archers left their post against the Prophet\u2019s orders, and the Muslims suffered heavy losses. His uncle Hamzah was among the martyrs. The lesson of obedience stayed with the Muslims.']},{id:'khandaq',when:'627 CE \xb7 5 AH',place:'Madinah',title:'The Battle of the Trench',body:['A huge army surrounded Madinah. On the advice of Salman al-Farisi, the Muslims dug a trench, and after weeks of siege, a storm sent the army home.']},{id:'hudaybiyyah',when:'628 CE \xb7 6 AH',place:'Journey',title:'The Treaty of Hudaybiyyah',body:['The Muslims set out for umrah and were stopped outside Makkah. The Prophet \ufdfa agreed to a peace treaty that seemed unfair to some, but Allah called it a clear victory, and many people entered Islam in the peace that followed.'],source:'Quran 48:1'},{id:'fath',when:'630 CE \xb7 8 AH',place:'Makkah',title:'The Conquest of Makkah',body:['He returned to Makkah with about 10,000 Muslims, almost without a fight. He forgave the people who had hurt him for years.','The idols were removed from the Kaaba, and Bilal climbed on top of it to call the adhan.']},{id:'farewell',when:'632 CE \xb7 10 AH',age:'63',place:'Makkah',title:'The Farewell Hajj',body:['He performed Hajj with a great crowd of Muslims and gave his famous sermon at Arafah, reminding them that every life, every honour and all property is sacred, and that no race is better than another except by taqwa.']},{id:'passing',when:'632 CE \xb7 11 AH',age:'63',place:'Madinah',title:'His passing',body:['He passed away in Madinah in the room of his wife Aisha, and was buried there.','Abu Bakr told the grieving people: "Whoever worshipped Muhammad, Muhammad has died. Whoever worships Allah, Allah is Ever-Living and does not die."'],source:'Sahih al-Bukhari 3668'}]},958,[]);